-- STEP-3 Data Validation Check

-- 1. Column Names Match Tables Exactly

DESC customers;
DESC categories;
DESC employees;
DESC supplier;
DESC products;
DESC orders;
DESC order_details;

-- STEP-4 Analysis Questions

-- Customer Insights

-- 1. How many unique customers have placed orders?

SELECT COUNT(distinct cust_id) as unique_customers
FROM orders;

-- 2. Which customers have placed the highest number of orders?

SELECT Cust_name c, COUNT(o.ord_id) as total_orders
from customers c
JOIN orders o ON c.cust_id=o.cust_id
GROUP BY c.cust_name
ORDER BY total_orders DESC;

-- 3. What is the total and average purchase value per customer?

SELECT c.cust_name,  SUM(od.total_price) as total_purchase,
AVG(od.total_price) as avg_purchase
FROM customers c
JOIN orders o ON c.cust_id=o.cust_id
JOIN order_details od ON o.ord_id=od.ord_id
GROUP BY c.cust_name
ORDER BY total_purchase DESC;

-- 4. Who are the top 5 customers by total purchase amount?

SELECT c.cust_name, SUM(od.total_price) as total_purchase
FROM customers c
JOIN orders o ON c.cust_id=o.cust_id
JOIN order_details od ON o.ord_id=od.ord_id
GROUP BY c.cust_name
order by total_purchase DESC
LIMIT 5;


-- Product Performance

-- 1. How many products exist in each category?

SELECT c.cat_name, COUNT(p.prod_id) as total_products
FROM categories c
JOIN products p ON c.cat_id=p.cat_id
GROUP BY c.cat_name
ORDER BY total_products DESC;

-- 2. What is the average price of products by category?

SELECT c.cat_name, AVG(p.price) as avg_price
FROM categories c
JOIN products p ON c.cat_id=p.cat_id
GROUP BY c.cat_name
ORDER BY avg_price DESC;

-- 3. Which products have the highest total sales volume (by quantity)?

SELECT p.prod_name, SUM(od.quantity) as total_quantity_sold
FROM products p
JOIN order_details od ON p.prod_id=od.prod_id
GROUP BY p.prod_name
ORDER BY total_quantity_sold DESC;

-- 4. What is the total revenue generated by each product?

SELECT p.prod_name , SUM(od.total_price) as tota_revenue
FROM products p
JOIN order_details od ON p.prod_id=od.prod_id
GROUP BY p.prod_name
ORDER BY tota_revenue DESC;

-- 5. How do product sales vary by category and supplier?

SELECT c.cat_name, s.sup_name, SUM(od.total_price) as total_sales
FROM order_details od
JOIN products p ON od.prod_id=p.prod_id
JOIN categories c ON p.cat_id=c.cat_id
JOIN supplier s ON p.sup_id=s.sup_id
GROUP BY c.cat_name, s.sup_name
ORDER BY total_sales DESC;


-- Sales and Order Trends

-- 1. How many orders have been placed in total?

SELECT COUNT(ord_id) as total_orders
FROM orders;

-- 2. What is the average value per order?

SELECT AVG(ord_id) as avg_order_value
FROM orders;

-- 3. On which dates were the most orders placed?

SELECT order_date, COUNT(ord_id) as total_orders
FROM orders
GROUP BY order_date
ORDER BY total_orders DESC;

-- 4. What are the monthly trends in order volume and revenue?

SELECT MONTH(o.order_date) AS month,
COUNT(DISTINCT o.ord_id) AS total_orders,
SUM(od.total_price) AS total_revenue
FROM orders o
JOIN order_details od ON o.ord_id = od.ord_id
GROUP BY MONTH(o.order_date)
ORDER BY month;

-- 5. How do order patterns vary across weekdays and weekends?

SELECT DAYNAME(order_date) as day_name,
COUNT(ord_id) as total_orders
from orders
group by day_name
order by total_orders DESC;

-- Supplier Contribution

-- 1. How many suppliers are there in the database?

SELECT COUNT(sup_id) as total_suppliers
from supplier;

-- 2. Which supplier provides the most products?

SELECT s.sup_name, count(prod_id) as total_products
from supplier s
JOIN products p ON s.sup_id=p.sup_id
group by s.sup_name
order by total_products desc;

-- 3. What is the average price of products from each supplier?

SELECT s.sup_name, avg(p.price) as avg_product_price
from supplier s 
JOIN products p ON s.sup_id=p.sup_id
group by s.sup_name
order by avg_product_price desc;

-- 4. Which suppliers contribute the most to total product sales (by revenue)?

SELECT s.sup_name, sum(od.total_price) as total_revenue
from supplier s 
JOIN products p ON s.sup_id=p.sup_id
JOIN order_details od ON p.prod_id=od.prod_id
group by s.sup_name
order by total_revenue desc;

-- Employee Performance

-- 1. How many employees have processed orders?

SELECT COUNT(distinct emp_id) as employees_processed_orders
FROM orders;

-- 2. Which employees have handled the most orders?

SELECT e.emp_name, COUNT(o.ord_id) as total_orders_handled
from employees e 
JOIN orders o ON e.emp_id=o.emp_id
GROUP BY e.emp_name
ORDER BY total_orders_handled DESC;

-- 3. What is the total sales value processed by each employee?

SELECT e.emp_name, SUM(od.total_price) as total_sales
FROM employees e
JOIN orders o ON e.emp_id=o.emp_id
JOIN order_details od ON o.ord_id=od.ord_id
GROUP BY e.emp_name
ORDER BY total_sales DESC;

-- 4. What is the average order value handled per employee?

SELECT e.emp_name, AVG(order_total) as avg_order_value
from employees e 
JOIN orders o ON e.emp_id=o.emp_id
JOIN (SELECT ord_id, SUM(total_price) AS order_total
FROM order_details
GROUP BY ord_id) AS order_summary
ON o.ord_id = order_summary.ord_id
GROUP BY e.emp_name
ORDER BY avg_order_value DESC;

-- Order Details Deep Dive

-- 1. What is the relationship between quantity ordered and total price?

SELECT quantity, sum(total_price) as total_sales
from order_details
group by quantity
order by quantity;

-- 2. What is the average quantity ordered per product?
 
SELECT p.prod_name, avg(od.quantity) as avg_quantity
from products p 
JOIN order_details od ON p.prod_id=od.prod_id
group by p.prod_name
order by avg_quantity desc;

-- 3. How does the unit price vary across products and orders?

SELECT p.prod_name, 
min(od.each_price) as min_price,
max(od.each_price) as max_price,
avg(od.each_price) as avg_price
from products p
JOIN order_details od ON p.prod_id=od.prod_id
group by p.prod_name
order by avg_price desc;



 